def get_authorization_scheme_param(
    authorization_header_value: str | None,
) -> tuple[str, str]:
    if not authorization_header_value:
        return "", ""
    scheme, _, param = authorization_header_value.partition(" ")
    return scheme, param.strip()

def _check_single_line(v: str | None, field_name: str) -> str | None:
    if v is not None and ("\r" in v or "\n" in v):
        raise ValueError(f"SSE '{field_name}' must be a single line")
    return v

def _check_id_valid(v: str | None) -> str | None:
    if v is not None and "\0" in v:
        raise ValueError("SSE 'id' must not contain null characters")
    return _check_single_line(v, "id")

def format_sse_event(
    *,
    data_str: Annotated[
        str | None,
        Doc(
            """
            Pre-serialized data string to use as the `data:` field.
            """
        ),
    ] = None,
    event: Annotated[
        str | None,
        Doc(
            """
            Optional event type name (`event:` field).
            """
        ),
    ] = None,
    id: Annotated[
        str | None,
        Doc(
            """
            Optional event ID (`id:` field).
            """
        ),
    ] = None,
    retry: Annotated[
        int | None,
        Doc(
            """
            Optional reconnection time in milliseconds (`retry:` field).
            """
        ),
    ] = None,
    comment: Annotated[
        str | None,
        Doc(
            """
            Optional comment line(s) (`:` prefix).
            """
        ),
    ] = None,
) -> bytes:
    """Build SSE wire-format bytes from **pre-serialized** data.

    The result always ends with `\\n\\n` (the event terminator).
    """
    lines: list[str] = []

    if comment is not None:
        for line in _split_sse_lines(comment):
            lines.append(f": {line}")

    if event is not None:
        lines.append(f"event: {event}")

    if data_str is not None:
        for line in _split_sse_lines(data_str):
            lines.append(f"data: {line}")

    if id is not None:
        lines.append(f"id: {id}")

    if retry is not None:
        lines.append(f"retry: {retry}")

    lines.append("")
    lines.append("")
    return "\n".join(lines).encode("utf-8")

def _check_data_exclusive(self) -> "ServerSentEvent":
    if self.data is not None and self.raw_data is not None:
        raise ValueError(
            "Cannot set both 'data' and 'raw_data' on the same "
            "ServerSentEvent. Use 'data' for JSON-serialized payloads "
            "or 'raw_data' for pre-formatted strings."
        )
    return self

def _get_request_telemetry(context: Context | None = None) -> _RequestTelemetry | None:
    value = otel_context.get_value(_REQUEST_TELEMETRY_KEY, context)
    return value if isinstance(value, _RequestTelemetry) else None

def _validation_failed(
    exc: RequestValidationError | WebSocketRequestValidationError,
) -> None:
    request_telemetry = _get_request_telemetry()
    if request_telemetry is None:
        return
    if request_telemetry.data is not None:
        if isinstance(exc, RequestValidationError):
            request_telemetry.data.body = exc.body
        request_telemetry.data.errors = exc.errors()
    if request_telemetry.logger is not None:
        attributes: dict[str, Any] = {
            "fastapi.validation.error_count": len(exc.errors())
        }
        if request_telemetry.route is not None:
            attributes["http.route"] = request_telemetry.route
        request_telemetry.logger.emit(
            event_name="fastapi.validation.failed",
            timestamp=time_ns(),
            severity_number=SeverityNumber.WARN,
            severity_text="WARN",
            body="Request validation failed",
            attributes=attributes,

def _exception_type(exc: BaseException) -> str:
    cls = type(exc)
    return (
        f"{cls.__module__}.{cls.__qualname__}"
        if cls.__module__ != "builtins"
        else cls.__qualname__

def _operation(
    *, name: str, function: Callable[..., Any] | None = None
) -> AbstractContextManager[None]:
    request_telemetry = _get_request_telemetry()
    if request_telemetry is None or request_telemetry.tracer is None:
        return _NO_OPERATION
    return _traced_operation(
        request_telemetry=request_telemetry, name=name, function=function

def _traced_operation(
    *,
    request_telemetry: _RequestTelemetry,
    name: str,
    function: Callable[..., Any] | None,
) -> Iterator[None]:
    assert request_telemetry.tracer is not None
    attributes = {}
    if function is not None:
        module = getattr(function, "__module__", type(function).__module__)
        qualname = getattr(function, "__qualname__", type(function).__qualname__)
        attributes["code.function.name"] = f"{module}.{qualname}"
    with request_telemetry.tracer.start_as_current_span(
        f"fastapi.{name}",
        attributes=attributes,
        record_exception=False,
        set_status_on_exception=False,
    ) as span:
        try:
            yield
        except Exception as exc:
            if name == "background_task" or (
                not isinstance(
                    exc,
                    (
                        HTTPException,
                        RequestValidationError,
                        WebSocketException,
                        WebSocketRequestValidationError,
                    ),
                )
                and not _normal_websocket_disconnect(exc)
            ):
                span.set_attribute("error.type", _exception_type(exc))
                span.set_status(StatusCode.ERROR)
            raise

def _run_sync_endpoint(
    *, function: Callable[..., Any], arguments: dict[str, Any]
) -> Any:
    with _operation(name="endpoint", function=function):
        return function(**arguments)

def _route_selected(
    *, scope: MutableMapping[str, Any], path: str | None, mount: bool = False
) -> None:
    request_telemetry = scope.get("fastapi.telemetry")
    if not isinstance(request_telemetry, _RequestTelemetry) or path is None:
        return
    # Mount's path_format ends in /{path}. The child contributes its own path.
    if mount:
        path = path.removesuffix("/{path}")
        request_telemetry._mount_prefix += path
        request_telemetry.route = request_telemetry._mount_prefix + "/{path}"
    else:
        request_telemetry.route = request_telemetry._mount_prefix + path
    if request_telemetry.span is not None:
        request_telemetry.span.set_attribute("http.route", request_telemetry.route)
        request_telemetry.span.update_name(
            f"{request_telemetry.span_method} {request_telemetry.route}"

def _legacy_otel(stack: Any) -> bool:
    # Test the built stack, not contrib's flag: that flag also exists when its
    # stack patch failed, or when instrument_app was called after stack creation.
    seen: set[int] = set()
    while stack is not None and id(stack) not in seen:
        seen.add(id(stack))
        if (
            type(stack).__module__ == "opentelemetry.instrumentation.asgi"
            and type(stack).__name__ == "OpenTelemetryMiddleware"
        ):
            return True
        stack = getattr(stack, "app", None)
    return False

def _exception(*, scope: Scope, exc: BaseException) -> None:
    if scope["type"] == "websocket" and _normal_websocket_disconnect(exc):
        return
    request_telemetry = scope.get("fastapi.telemetry")
    if isinstance(request_telemetry, _RequestTelemetry):
        seen = request_telemetry._exceptions
        if not any(previous is exc for previous in seen):
            seen.append(exc)
            if request_telemetry.logger is not None and isinstance(exc, Exception):
                attributes = (
                    {"http.route": request_telemetry.route}
                    if request_telemetry.route
                    else None
                )
                request_telemetry.logger.emit(
                    exception=exc,
                    event_name="fastapi.websocket.exception"
                    if scope["type"] == "websocket"
                    else "http.server.request.exception",
                    timestamp=time_ns(),
                    severity_number=SeverityNumber.ERROR,
                    severity_text="ERROR",
                    body="Unhandled exception in FastAPI WebSocket connection"
                    if scope["type"] == "websocket"
                    else "Unhandled exception in FastAPI request",
                    attributes=attributes,

def _server_attributes(scope: Scope) -> dict[str, Any]:
    # ASGI exposes HTTP/2 and HTTP/3 authority as Host. Proxy normalization is
    # handled by the server or middleware, as it is for the request URL.
    authority = Headers(scope=scope).get("host")
    if authority is not None:
        try:
            url = urlsplit("//" + authority)
            address, port = url.hostname, url.port
        except ValueError:
            # Malformed authority must not prevent handling the request.
            return {}
        if url.username is not None or url.path or url.query or url.fragment:
            return {}
        if port is None:
            port = {"http": 80, "https": 443, "ws": 80, "wss": 443}.get(
                scope.get("scheme", "http")
            )
    else:
        address, port = scope.get("server") or (None, None)
    if address is None:
        return {}
    attributes: dict[str, Any] = {"server.address": address}
    if port is not None:
        attributes["server.port"] = port
    return attributes

def get(self, carrier: Headers, key: str) -> list[str] | None:
    values = carrier.getlist(key)
    if not values:
        return None
    if key.lower() == "baggage":
        # The baggage propagator reads only the first value.
        return [",".join(values)]
    return values

async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    try:
        await self.app(scope, receive, send)
    except Exception as exc:
        _exception(scope=scope, exc=exc)
        raise

def _get_tracer(self, *, provider: trace.TracerProvider) -> trace.Tracer:
    if provider is not self._tracer_provider:
        self._tracer = provider.get_tracer(
            "fastapi", __version__, schema_url=_SCHEMA_URL
        )
        self._tracer_provider = provider
    assert self._tracer is not None
    return self._tracer

async def __call__(
    self,
    *,
    app: ASGIApp,
    scope: Scope,
    receive: Receive,
    send: Send,
    legacy_otel: bool = False,
) -> None:
    config = self.config
    if config["exclude"] is not None and config["exclude"](scope):
        # Keep mounted FastAPI apps from observing this excluded request.
        scope["fastapi.telemetry"] = None
        # An in-process request can inherit another request's telemetry.
        token = otel_context.attach(
            otel_context.set_value(_REQUEST_TELEMETRY_KEY, None)
        )
        try:
            await app(scope, receive, send)
        finally:
            otel_context.detach(token)
            scope.pop("fastapi.telemetry", None)
        return
    tracing = config["tracing"] and not legacy_otel
    logging = config["logs"] and not legacy_otel
    if logging:
        logger_provider = config["logger_provider"] or _logs.get_logger_provider()
        logging = not (
            (config["logger_provider"] is None and _unconfigured(logger_provider))
            or isinstance(logger_provider, _logs.NoOpLoggerProvider)
        )
    is_websocket = scope["type"] == "websocket"
    metering = config["metrics"] and not legacy_otel and not is_websocket
    if tracing:
        provider = config["tracer_provider"] or trace.get_tracer_provider()
        tracing = not (
            (config["tracer_provider"] is None and _unconfigured(provider))
            or isinstance(provider, trace.NoOpTracerProvider)
        )
    if metering:
        meter_provider = config["meter_provider"] or metrics.get_meter_provider()
        metering = not (
            (config["meter_provider"] is None and _unconfigured(meter_provider))
            or isinstance(meter_provider, metrics.NoOpMeterProvider)
        )
    if not tracing and not metering and not logging:
        await app(scope, receive, send)
        return
    original_method = scope.get("method", "")
    method = original_method if original_method in self._known_methods else "_OTHER"
    span_method = "WS" if is_websocket else "HTTP" if method == "_OTHER" else method
    attributes: dict[str, Any] = {
        "url.scheme": scope.get("scheme", "ws" if is_websocket else "http"),
    }
    if is_websocket:
        attributes["network.protocol.name"] = "websocket"
    else:
        attributes["http.request.method"] = method
        if scope.get("http_version"):
            attributes["network.protocol.version"] = scope["http_version"]
    duration, active = self._instruments() if metering else (None, None)
    active_attributes = {
        k: v for k, v in attributes.items() if k != "network.protocol.version"
    }
    if active is not None:
        active.add(1, active_attributes)
    started = perf_counter()
    span = None
    tracer = None
    parent_token = None
    if tracing:
        parent = propagate.extract(Headers(scope=scope), getter=_HEADERS_GETTER)
        parent_token = otel_context.attach(parent)
        tracer = self._get_tracer(provider=provider)
        span_attributes = {**attributes, **_server_attributes(scope)}
        if not is_websocket:
            span_attributes["url.path"] = scope["path"]
            if scope.get("query_string"):
                span_attributes["url.query"] = urlencode(
                    [
                        (
                            key,
                            "REDACTED"
                            if key in _SENSITIVE_QUERY_PARAMETERS
                            else value,
                        )
                        for key, value in parse_qsl(
                            scope["query_string"].decode("latin-1"),
                            keep_blank_values=True,
                        )
                    ]
                )
            if original_method != method:
                span_attributes["http.request.method_original"] = original_method
        span = tracer.start_span(
            span_method,
            context=parent,
            kind=SpanKind.SERVER,
            attributes=span_attributes,
        )
    request_telemetry = _RequestTelemetry(
        span=span,
        span_method=span_method,
        tracer=tracer if config["operation_spans"] else None,
        logger=_logs.get_logger(
            "fastapi",
            __version__,
            config["logger_provider"],
            schema_url=_SCHEMA_URL,
        )
        if logging
        else None,
        _mount_prefix=scope.get("app_root_path", scope.get("root_path", "")).rstrip(
            "/"
        ),
    )
    scope["fastapi.telemetry"] = request_telemetry
    token = otel_context.attach(
        otel_context.set_value(_REQUEST_TELEMETRY_KEY, request_telemetry)
    )
    finished = False
    trailers = False
    disconnected = False

    def finish(error: BaseException | None = None) -> None:
        nonlocal finished
        if finished:
            return
        finished = True
        if request_telemetry.route is not None:
            attributes["http.route"] = request_telemetry.route
        if request_telemetry.status_code is not None:
            attributes["http.response.status_code"] = request_telemetry.status_code
        failed = (
            error is not None
            or not is_websocket
            and (
                request_telemetry.status_code is None
                or request_telemetry.status_code >= 500
            )
        )
        if failed:
            errors = request_telemetry._exceptions
            failure = error or (errors[-1] if errors else None)
            attributes["error.type"] = (
                _exception_type(failure)
                if failure
                else str(request_telemetry.status_code or "incomplete_response")
            )
        if span is not None:
            span.set_attributes(attributes)
            if failed:
                span.set_status(StatusCode.ERROR)
        # Record while the span is current, so exemplars can correlate it.
        if duration is not None:
            duration.record(max(0, perf_counter() - started), attributes)
        if active is not None:
            active.add(-1, active_attributes)
        if span is not None:
            span.end()

    async def wrapped_send(message: Message) -> None:
        nonlocal trailers
        if message["type"] == "http.response.start":
            request_telemetry.status_code = message["status"]
            trailers = message.get("trailers", False)
        await send(message)
        if (
            (
                message["type"] == "http.response.body"
                and not message.get("more_body", False)
                and not trailers
            )
            or (
                message["type"] == "http.response.trailers"
                and not message.get("more_trailers", False)
            )
            or message["type"] == "http.response.pathsend"
        ):
            finish()

    async def wrapped_receive() -> Message:
        nonlocal disconnected
        message = await receive()
        if message["type"] == "http.disconnect":
            disconnected = True
        return message

    context = (
        trace.use_span(
            span,
            end_on_exit=False,
            record_exception=False,
            set_status_on_exception=False,
        )
        if span is not None
        else nullcontext()
    )
    try:
        with context:
            try:
                await app(
                    scope,
                    receive if is_websocket else wrapped_receive,
                    send if is_websocket else wrapped_send,
                )
            except BaseException as exc:
                _exception(scope=scope, exc=exc)
                finish(
                    None
                    if is_websocket and _normal_websocket_disconnect(exc)
                    else exc
                )
                raise
            finally:
                if not finished:
                    finish(
                        None
                        if is_websocket
                        else ConnectionError("Client disconnected")
                        if disconnected
                        else RuntimeError("Incomplete ASGI response")
                    )
    finally:
        request_telemetry.data = None
        request_telemetry._exceptions.clear()
        otel_context.detach(token)
        scope.pop("fastapi.telemetry", None)
        if parent_token is not None:
            otel_context.detach(parent_token)

def _flush() -> None:
    for component in tuple(_owned):
        try:
            component.force_flush()
        except Exception:
            logger.exception("FastAPI telemetry cleanup failed")

def _shutdown() -> None:
    with _lock:
        owned = tuple(_owned)
        _owned.clear()
    for component in owned:
        try:
            component.shutdown()
        except Exception:
            logger.exception("FastAPI telemetry cleanup failed")

def _export_endpoint(signal: str) -> str | None:
    exporter = (os.getenv(f"OTEL_{signal}_EXPORTER") or "otlp").strip().lower()
    endpoint = os.getenv(f"OTEL_EXPORTER_OTLP_{signal}_ENDPOINT")
    if not endpoint:
        endpoint = os.getenv("OTEL_EXPORTER_OTLP_ENDPOINT")
        if endpoint:
            endpoint = f"{endpoint.removesuffix('/')}/v1/{signal.lower()}"
    if not endpoint or exporter == "none":
        return None
    if exporter != "otlp":
        raise FastAPIError(
            f"FastAPI automatic telemetry supports OTEL_{signal}_EXPORTER=otlp or none. "
            "Configure other exporters explicitly and pass telemetry={'auto_configure': False} to FastAPI()."
        )
    protocol = (
        os.getenv(f"OTEL_EXPORTER_OTLP_{signal}_PROTOCOL")
        or os.getenv("OTEL_EXPORTER_OTLP_PROTOCOL")
        or "http/protobuf"
    )
    if protocol != "http/protobuf":
        raise FastAPIError(
            "FastAPI automatic telemetry requires the OTLP http/protobuf protocol. Configure other transports explicitly and pass telemetry={'auto_configure': False} to FastAPI()."
        )
    parsed = urlsplit(endpoint)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        raise FastAPIError(
            f"Invalid OTLP {signal.lower()} endpoint. Use an absolute HTTP or HTTPS URL."
        )
    return endpoint

def _registration_provider(provider: Any) -> Any:
    # Older Logfire meter wrappers do not expose add_metric_reader(). Attach
    # the reader to their SDK provider. Measurements still use the original wrapper.
    if (
        type(provider).__module__ == "logfire._internal.metrics"
        and type(provider).__name__ == "ProxyMeterProvider"
        and not hasattr(provider, "add_metric_reader")
    ):
        return provider.provider
    return provider

def _configure_from_environment(config: TelemetryConfig) -> None:
    """Add OTLP exporters from the environment to the selected providers.

    Called automatically before ASGI lifespan startup. Existing providers and
    their exporters are preserved. FastAPI registers its own export components once
    per provider. It does not inspect or deduplicate other components' exporters.
    Enable with `FASTAPI_OTEL_AUTO_CONFIGURE=true` or pass
    `telemetry={"auto_configure": True}` to `FastAPI()`.
    """
    if (
        not config["auto_configure"]
        or os.getenv("OTEL_SDK_DISABLED", "").lower() == "true"
    ):
        return
    with _lock:
        signals = [
            ("TRACES", config["tracing"], config["tracer_provider"]),
            ("METRICS", config["metrics"], config["meter_provider"]),
            ("LOGS", config["logs"], config["logger_provider"]),
        ]
        requested = [
            (signal, provider, endpoint)
            for signal, enabled, provider in signals
            if enabled and (endpoint := _export_endpoint(signal)) is not None
        ]
        if not requested:
            return
        try:
            from opentelemetry.exporter.otlp.proto.http._log_exporter import (
                OTLPLogExporter,
            )
            from opentelemetry.exporter.otlp.proto.http.metric_exporter import (
                OTLPMetricExporter,
            )
            from opentelemetry.exporter.otlp.proto.http.trace_exporter import (
                OTLPSpanExporter,
            )
            from opentelemetry.sdk._logs import LoggerProvider
            from opentelemetry.sdk._logs.export import BatchLogRecordProcessor
            from opentelemetry.sdk.metrics import MeterProvider
            from opentelemetry.sdk.metrics.export import PeriodicExportingMetricReader
            from opentelemetry.sdk.trace import TracerProvider
            from opentelemetry.sdk.trace.export import BatchSpanProcessor
        except ImportError as exc:
            raise FastAPIError(
                "Automatic OpenTelemetry export requires fastapi[opentelemetry] or fastapi[standard]. Install the extra, configure providers yourself, or pass telemetry={'auto_configure': False} to FastAPI()."
            ) from exc
        # The SDK's registration methods also allow vendor wrappers to forward
        # additions. Keep a record of our own registrations, without examining
        # another component's exporters or their destinations.
        providers = {
            "TRACES": ("tracer", trace.get_tracer_provider),
            "METRICS": ("meter", metrics.get_meter_provider),
            "LOGS": ("logger", _logs.get_logger_provider),
        }

        def create_component(*, signal: str, endpoint: str) -> Any:
            if signal == "TRACES":
                return BatchSpanProcessor(OTLPSpanExporter(endpoint=endpoint))
            if signal == "METRICS":
                return PeriodicExportingMetricReader(
                    OTLPMetricExporter(endpoint=endpoint)
                )
            return BatchLogRecordProcessor(OTLPLogExporter(endpoint=endpoint))

        for signal, explicit, endpoint in requested:
            name, get_provider = providers[signal]
            provider = _registration_provider(
                explicit if explicit is not None else get_provider()
            )
            if any(s == signal and p is provider for s, p in _configured):
                continue
            if explicit is None and _unconfigured(provider):
                component = create_component(signal=signal, endpoint=endpoint)
                if signal == "TRACES":
                    provider = TracerProvider(shutdown_on_exit=False)
                    provider.add_span_processor(component)
                    trace.set_tracer_provider(provider)
                elif signal == "METRICS":
                    provider = MeterProvider(
                        metric_readers=[component], shutdown_on_exit=False
                    )
                    metrics.set_meter_provider(provider)
                else:
                    provider = LoggerProvider(shutdown_on_exit=False)
                    provider.add_log_record_processor(component)
                    _logs.set_logger_provider(provider)
                current = get_provider()
                if current is provider:
                    _configured.append((signal, provider))
                    _owned.append(provider)
                    continue
                # Another component configured the global provider concurrently.
                # Close the unused pipeline and attach a new component to theirs.
                provider.shutdown()
                provider = _registration_provider(current)
            # Vendor wrappers can expose the SDK registration methods without
            # inheriting its provider classes. Check each method against its SDK
            # class statically and its availability on the provider at runtime.
            register: Callable[[Any], None] | None
            try:
                if signal == "TRACES":
                    register = cast(TracerProvider, provider).add_span_processor
                elif signal == "METRICS":
                    register = cast(MeterProvider, provider).add_metric_reader
                else:
                    register = cast(LoggerProvider, provider).add_log_record_processor
            except AttributeError:
                register = None
            if not callable(register):
                raise FastAPIError(
                    f"The configured OpenTelemetry {name} provider does not support "
                    "adding an OTLP exporter. Configure environment export through "
                    "that provider and pass telemetry={'auto_configure': False} to FastAPI()."
                )
            component = create_component(signal=signal, endpoint=endpoint)
            try:
                register(component)
            except Exception:
                component.shutdown()
                raise
            _configured.append((signal, provider))
            _owned.append(component)

async def lifespan(
    *, config: TelemetryConfig, app: ASGIApp, scope: Scope, receive: Receive, send: Send
) -> None:
    async def wrapped_receive() -> Message:
        message = await receive()
        if message["type"] == "lifespan.startup":
            try:
                _configure_from_environment(config)
            except Exception as exc:
                # Optional telemetry setup must not prevent application startup.
                logger.warning(
                    "FastAPI automatic telemetry configuration failed: %s", exc
                )
        return message

    async def wrapped_send(message: Message) -> None:
        if (
            message["type"]
            in {
                "lifespan.shutdown.complete",
                "lifespan.shutdown.failed",
                "lifespan.startup.failed",
            }
            and _owned
        ):
            await run_sync(_flush)
        await send(message)

    await app(scope, wrapped_receive, wrapped_send)

def is_body_allowed_for_status_code(status_code: int | str | None) -> bool:
    if status_code is None:
        return True
    # Ref: https://github.com/OAI/OpenAPI-Specification/blob/main/versions/3.1.0.md#patterned-fields-1
    if status_code in {
        "default",
        "1XX",
        "2XX",
        "3XX",
        "4XX",
        "5XX",
    }:
        return True
    current_status_code = int(status_code)
    return not (current_status_code < 200 or current_status_code in {204, 205, 304})

def create_model_field(
    name: str,
    type_: Any,
    default: Any | None = Undefined,
    field_info: FieldInfo | None = None,
    alias: str | None = None,
    mode: Literal["validation", "serialization"] = "validation",
) -> ModelField:
    if annotation_is_pydantic_v1(type_):
        raise PydanticV1NotSupportedError(
            "pydantic.v1 models are no longer supported by FastAPI."
            f" Please update the response model {type_!r}."
        )
    field_info = field_info or FieldInfo(annotation=type_, default=default, alias=alias)
    try:
        return v2.ModelField(mode=mode, name=name, field_info=field_info)
    except PydanticSchemaGenerationError:
        raise fastapi.exceptions.FastAPIError(
            _invalid_args_message.format(type_=type_)
        ) from None

def deep_dict_update(main_dict: dict[Any, Any], update_dict: dict[Any, Any]) -> None:
    for key, value in update_dict.items():
        if (
            key in main_dict
            and isinstance(main_dict[key], dict)
            and isinstance(value, dict)
        ):
            deep_dict_update(main_dict[key], value)
        elif (
            key in main_dict
            and isinstance(main_dict[key], list)
            and isinstance(update_dict[key], list)
        ):
            main_dict[key] = main_dict[key] + update_dict[key]
        else:
            main_dict[key] = value
